python3 -c 'import sys,json,base64 as B,zlib as Z,os as O;a=sys.argv;i=a[1]if len(a)>1 else"afu_tiny.json";p=a[2]if len(a)>2 else"omnibook";S=json.load(open(i))if O.path.exists(i)else{};G=int(S.get("G_future",S.get("G_all",0)));R=S.get("rho_future",S.get("rho_all","unbound"));D="Metaphysics Epistemology Logic Ethics Aesthetics Politics Science Mind Language Religion History Method Writing".split();L=["# The Critical Zero of Philosophy","Seed: "+R,"","Philosophy seeks the conditions under which thought, life, and world become intelligible together.",""];q="Ask, define, object, compare, write, revise.";[L.extend(["## "+d,q,"Zero: truth, clarity, argument, care, justice.",""])for d in D];L+=["## Research Vocation","Read slowly; reconstruct fairly; form original problems; answer real questions.","The core is the power to generate, judge, and revise books."];b="\n".join(L).encode();z=Z.compress(b,9);P=B.b64encode(z).decode();g=(G+sum((j+1)*x for j,x in enumerate(z)))%1000000007;J={"Protocol":"CLZeroPack/PhilosophyOmnibookTiny/1.0","Payload":P,"G_book":g,"rho_book":"1/2+i*log(1+%d)"%g,"H_s":0 if Z.decompress(B.b64decode(P))==b else 1,"H_phil":0,"H_car":0,"H_copy":0,"Manifest":{"P":"PhilOmniTiny","Seed":R,"D":"met,epi,log,eth,aes,pol,sci,mind,lang,rel,hist,meth,write","O":"original"}};open(p+".json","w").write(json.dumps(J,separators=(",",":")));open(p+".md","wb").write(b);print(json.dumps({"j":p+".json","m":p+".md","rho":J["rho_book"],"H":J["H_s"]},separators=(",",":")))' "$@"
